#include <ArduinoJson.h>
#include "../include/types.h"
#include "../drivers/motor_driver.h"

// Frame types (from PROTOCOLS_CONTRACT.md)
enum class FrameType : uint8_t {
    STATUS_REPORT      = 0x01,
    POSITION_CMD       = 0x02,
    VELOCITY_CMD       = 0x03,
    TORQUE_CMD         = 0x04,
    PARAM_READ         = 0x05,
    PARAM_WRITE        = 0x06,
    DIAGNOSTIC         = 0x07,
    FIRMWARE_UPDATE    = 0x08,
    HEARTBEAT          = 0x09,
    RESERVED           = 0x0A
};

// Motor series enumeration
enum class MotorSeries : uint8_t {
    RMD_X = 0x01,
    RH = 0x02,
    CEM = 0x03,
    RMD_H = 0x04,
    RMD_L = 0x05,
    FL = 0x06
};

// Drive type
enum class DriveType : uint8_t {
    STANDARD = 0x01,
    BRAKE = 0x02
};

// Gearbox type
enum class GearboxType : uint8_t {
    PLANETARY = 0x01,
    HARMONIC = 0x02,
    DIRECT = 0x03,
    CYCLOID = 0x04,
    LINEAR = 0x05
};

// Communication type
enum class Communication : uint8_t {
    CAN = 0x01,
    RS485 = 0x02,
    ETHERCAT = 0x03
};

// Motor configuration
struct MotorConfig {
    uint8_t motorId;
    uint8_t protocol;
    float maxVelocity;
    float maxTorque;
    float kp;
    float ki;
    float kd;
};

// Protocol abstraction layer
class ProtocolAbstractionLayer {
public:
    ProtocolAbstractionLayer();
    ~ProtocolAbstractionLayer();

    bool initialize(uint8_t protocolType);
    void deinitialize();

    bool sendFrame(const uint8_t* data, uint8_t length);
    bool receiveFrame(uint8_t* data, uint8_t maxLength, uint8_t& receivedLength);

    void setMotorId(uint8_t motorId);
    uint8_t getMotorId() const;

    bool isConnected() const;

private:
    uint8_t _motorId;
    uint8_t _protocolType;
    bool _initialized;
};"}

